      .filter(c => c.tipo === 'Nutrición' && c.antropometria)
      .sort((a, b) => new Date(a.fecha).getTime() - new Date(b.fecha).getTime());

    return nutConsultations.map(c => ({
      fecha: c.fecha,
      peso: c.antropometria?.peso,
